INSERT INTO collection_pages VALUES('4640f82a5460a0cfa723a331a13ae667a652e7c4e41a95304f7fff817f745c94','72c512abf334cd76d5a424ad81c7c9d797a5ddee8a700a045a9dbac93e682a98','{"hasNext":false,"items":[{"author":{"account":{"login":"google-labs-jules[bot]","providerType":"Bot"},"email":"161369871+google-labs-jules[bot]@users.noreply.github.com","name":"google-labs-jules[bot]"},"authoredDate":"2025-06-12T12:41:49Z","committedDate":"2025-06-12T12:41:49Z","committer":{"account":{"login":"google-labs-jules[bot]","providerType":"Bot"},"email":"161369871+google-labs-jules[bot]@users.noreply.github.com","name":"google-labs-jules[bot]"},"observedAt":"2026-10-08T19:27:46.433Z","repositoryId":1000842465,"sha":"cb055a4e1ab26afb0f842734f123fb9ec07d0fd4"}],"observedAt":"2026-10-08T19:27:46.433Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/in/842251?v=4","events_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/events{/privacy}","followers_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/followers","following_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/following{/other_user}","gists_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/apps/google-labs-jules","id":161369871,"login":"google-labs-jules[bot]","node_id":"BOT_kgDOCZ5PDw","organizations_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/orgs","received_events_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/received_events","repos_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/repos","site_admin":false,"starred_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/subscriptions","type":"Bot","url":"https://api.github.com/users/google-labs-jules%5Bbot%5D","user_view_type":"public"},"comments_url":"https://api.github.com/repos/rekha-beniwal/angular_remote/commits/cb055a4e1ab26afb0f842734f123fb9ec07d0fd4/comments","commit":{"author":{"date":"2025-06-12T12:41:49Z","email":"161369871+google-labs-jules[bot]@users.noreply.github.com","name":"google-labs-jules[bot]"},"comment_count":0,"committer":{"date":"2025-06-12T12:41:49Z","email":"161369871+google-labs-jules[bot]@users.noreply.github.com","name":"google-labs-jules[bot]"},"message":"feat: Implement Module Federation between Angular remote and React host\n\nI''ve set up a monorepo-like structure with two applications:\n\n1.  **Angular Remote (`angular_remote`):**\n    *   Initialized as an Angular application (v20).\n    *   Configured with `@angular-architects/module-federation` to act as a remote.\n    *   Exposes its main `AppComponent` (as `angular_remote/Component`).\n    *   Integrates Bootstrap CSS (via global styles) and JS (via main bootstrap process). These assets are bundled with the remote and made available to the host when the remote component is loaded.\n    *   Serves on port 4201.\n\n2.  **React Host (`react_host`):**\n    *   Initialized as a React application using Vite.\n    *   Configured with `@originjs/vite-plugin-federation` to act as a host.\n    *   Consumes the `angular_remote/Component` from the Angular application.\n    *   Dynamically loads and renders the Angular component.\n    *   Relies on the federated Angular component to provide Bootstrap styling and JavaScript functionality, without direct Bootstrap links in its own `index.html`.\n    *   Serves on port 5001.\n\nThis setup demonstrates module federation sharing an Angular component, along with its bundled Bootstrap assets, to a React host application.","tree":{"sha":"ead5d2091c4b5ba4ca48de68b6da87c26c9f33a9","url":"https://api.github.com/repos/rekha-beniwal/angular_remote/git/trees/ead5d2091c4b5ba4ca48de68b6da87c26c9f33a9"},"url":"https://api.github.com/repos/rekha-beniwal/angular_remote/git/commits/cb055a4e1ab26afb0f842734f123fb9ec07d0fd4","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/in/842251?v=4","events_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/events{/privacy}","followers_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/followers","following_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/following{/other_user}","gists_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/apps/google-labs-jules","id":161369871,"login":"google-labs-jules[bot]","node_id":"BOT_kgDOCZ5PDw","organizations_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/orgs","received_events_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/received_events","repos_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/repos","site_admin":false,"starred_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/google-labs-jules%5Bbot%5D/subscriptions","type":"Bot","url":"https://api.github.com/users/google-labs-jules%5Bbot%5D","user_view_type":"public"},"html_url":"https://github.com/rekha-beniwal/angular_remote/commit/cb055a4e1ab26afb0f842734f123fb9ec07d0fd4","node_id":"C_kwDOO6ek4doAKGNiMDU1YTRlMWFiMjZhZmIwZjg0MjczNGYxMjNmYjllYzA3ZDBmZDQ","parents":[],"sha":"cb055a4e1ab26afb0f842734f123fb9ec07d0fd4","url":"https://api.github.com/repos/rekha-beniwal/angular_remote/commits/cb055a4e1ab26afb0f842734f123fb9ec07d0fd4"}],"requestUrl":"https://api.github.com/repos/rekha-beniwal/angular_remote/commits?per_page=100&page=1&sha=cb055a4e1ab26afb0f842734f123fb9ec07d0fd4&since=2025-03-31T23%3A59%3A59.000Z&until=2026-10-08T15%3A46%3A42.285Z"}');
